:root{
  --red:#b91c1c;--red2:#ef4444;--gold:#c9973a;--gold2:#f0c060;
  --bg:#0d0b09;--bg2:#130f0d;--bg3:#1a1410;
  --bd:#2e2118;--tx:#f5ede0;--tx2:#8c7a66;
  --serif:'Playfair Display',serif;--sans:'DM Sans',sans-serif;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{font-family:var(--sans);background:var(--bg);color:var(--tx);overflow-x:hidden}

/* SCROLLBAR */
::-webkit-scrollbar{width:4px}
::-webkit-scrollbar-thumb{background:var(--red);border-radius:2px}

/* NOISE OVERLAY */
body::before{
  content:'';position:fixed;inset:0;z-index:0;pointer-events:none;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.035'/%3E%3C/svg%3E");
  opacity:.4;
}

/* NAV */
.nav{position:fixed;top:0;left:0;right:0;z-index:100;
  display:flex;align-items:center;justify-content:space-between;
  padding:0 48px;height:72px;
  background:rgba(13,11,9,0.92);backdrop-filter:blur(20px);
  border-bottom:1px solid rgba(201,151,58,.12);
  transition:all .4s;
}
.nav.scrolled{height:60px;border-bottom-color:rgba(201,151,58,.2)}
.logo{font-family:var(--serif);font-size:22px;font-weight:900;color:var(--tx);text-decoration:none;display:flex;align-items:center;gap:12px;letter-spacing:-.5px}
.logo-badge{width:36px;height:36px;border-radius:50%;background:linear-gradient(135deg,var(--red),var(--gold));display:flex;align-items:center;justify-content:center;font-size:16px}
.nav-links{display:flex;gap:32px;align-items:center}
.nav-links a{font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:var(--tx2);text-decoration:none;transition:color .3s}
.nav-links a:hover{color:var(--tx)}
.nav-cta{padding:10px 24px;background:var(--red);color:#fff;border-radius:6px;font-size:12px;font-weight:500;letter-spacing:1px;text-transform:uppercase;text-decoration:none;transition:all .25s}
.nav-cta:hover{background:var(--red2);transform:translateY(-1px)}

/* HERO */
.hero{min-height:100vh;display:flex;align-items:center;position:relative;overflow:hidden;padding:0 48px}
.hero-bg{position:absolute;inset:0;z-index:0}
.hero-bg-inner{position:absolute;inset:0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(185,28,28,.07) 0%, transparent 60%),
    radial-gradient(ellipse 50% 80% at 10% 80%, rgba(201,151,58,.05) 0%, transparent 50%),
    linear-gradient(180deg, var(--bg) 0%, var(--bg2) 100%);
}
/* Decorative lines */
.hero-lines{position:absolute;right:0;top:0;bottom:0;width:45%;overflow:hidden;opacity:.04}
.hero-lines::before{content:'';position:absolute;inset:0;
  background:repeating-linear-gradient(90deg,var(--gold) 0,var(--gold) 1px,transparent 1px,transparent 40px);
}
.hero-lines::after{content:'';position:absolute;inset:0;
  background:repeating-linear-gradient(0deg,var(--gold) 0,var(--gold) 1px,transparent 1px,transparent 40px);
}

.hero-content{position:relative;z-index:2;max-width:620px}
.hero-tag{display:inline-flex;align-items:center;gap:8px;font-size:11px;letter-spacing:2.5px;text-transform:uppercase;color:var(--gold);margin-bottom:24px;
  padding:6px 16px;border:1px solid rgba(201,151,58,.3);border-radius:2px;background:rgba(201,151,58,.05)}
.hero-tag span{width:20px;height:1px;background:var(--gold);display:inline-block}

h1.hero-title{font-family:var(--serif);font-size:clamp(52px,6vw,88px);font-weight:900;line-height:.95;margin-bottom:24px;
  animation:fadeUp .8s ease both .2s}
h1.hero-title em{font-style:italic;color:var(--gold2);display:block}
h1.hero-title strong{color:var(--red2)}

.hero-desc{font-size:15px;color:var(--tx2);line-height:1.8;max-width:440px;margin-bottom:36px;font-weight:300;
  animation:fadeUp .8s ease both .4s}

.hero-actions{display:flex;gap:14px;flex-wrap:wrap;animation:fadeUp .8s ease both .5s}
.btn-primary{display:inline-flex;align-items:center;gap:10px;padding:16px 32px;background:var(--red);color:#fff;border-radius:6px;font-size:13px;font-weight:500;letter-spacing:.5px;text-decoration:none;transition:all .3s;position:relative;overflow:hidden}
.btn-primary::before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.08),transparent);transform:translateX(-100%);transition:transform .5s}
.btn-primary:hover::before{transform:translateX(100%)}
.btn-primary:hover{background:var(--red2);transform:translateY(-2px);box-shadow:0 8px 30px rgba(185,28,28,.3)}
.btn-outline{display:inline-flex;align-items:center;gap:10px;padding:15px 32px;background:transparent;color:var(--tx);border:1px solid var(--bd);border-radius:6px;font-size:13px;text-decoration:none;transition:all .3s}
.btn-outline:hover{border-color:var(--gold);color:var(--gold)}

.hero-stats{display:flex;gap:40px;margin-top:56px;padding-top:40px;border-top:1px solid var(--bd);animation:fadeUp .8s ease both .6s}
.stat-item .num{font-family:var(--serif);font-size:40px;font-weight:700;color:var(--gold2);line-height:1}
.stat-item .lbl{font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:var(--tx2);margin-top:4px}

/* HERO RIGHT VISUAL */
.hero-visual{position:absolute;right:48px;top:50%;transform:translateY(-50%);width:38%;z-index:1;
  animation:fadeIn 1.2s ease both .3s}
.hero-visual-inner{position:relative}
.hero-img-frame{width:100%;aspect-ratio:3/4;border-radius:4px;overflow:hidden;position:relative;
  background:var(--bg3);border:1px solid var(--bd);
  display:flex;align-items:center;justify-content:center;font-size:160px;opacity:.15}
.hero-badge{position:absolute;bottom:-20px;left:-20px;width:120px;height:120px;border-radius:50%;
  background:var(--red);display:flex;flex-direction:column;align-items:center;justify-content:center;
  font-family:var(--serif);border:3px solid var(--bg)}
.hero-badge .b-num{font-size:28px;font-weight:700;line-height:1;color:#fff}
.hero-badge .b-txt{font-size:9px;letter-spacing:1px;text-transform:uppercase;color:rgba(255,255,255,.7)}

/* STRIP */
.strip{background:var(--red);padding:14px 48px;display:flex;gap:48px;overflow:hidden;position:relative}
.strip-inner{display:flex;gap:48px;animation:marquee 18s linear infinite;white-space:nowrap}
.strip-item{display:flex;align-items:center;gap:10px;font-size:12px;letter-spacing:2px;text-transform:uppercase;color:rgba(255,255,255,.9)}
.strip-item i{font-size:10px;opacity:.6}

/* PRODUCTS */
.section{padding:100px 48px;position:relative;z-index:1}
.section-label{font-size:11px;letter-spacing:3px;text-transform:uppercase;color:var(--gold);margin-bottom:8px}
.section-title{font-family:var(--serif);font-size:clamp(36px,4vw,52px);font-weight:700;margin-bottom:40px;line-height:1.1}
.section-title em{font-style:italic;color:var(--tx2)}

.products-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:2px}
.product-card{background:var(--bg2);position:relative;overflow:hidden;cursor:pointer;group}
.product-card::after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.8) 0%,transparent 60%);z-index:1}
.product-img{width:100%;aspect-ratio:3/4;display:flex;align-items:center;justify-content:center;font-size:80px;
  background:var(--bg3);transition:transform .6s ease;filter:grayscale(.3)}
.product-card:hover .product-img{transform:scale(1.06)}
.product-info{position:absolute;bottom:0;left:0;right:0;padding:28px;z-index:2;transform:translateY(8px);transition:transform .4s}
.product-card:hover .product-info{transform:translateY(0)}
.product-tag{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--gold);margin-bottom:6px}
.product-name{font-family:var(--serif);font-size:24px;font-weight:700;margin-bottom:4px}
.product-desc{font-size:12px;color:rgba(255,255,255,.5);margin-bottom:12px;opacity:0;transition:opacity .4s .1s}
.product-card:hover .product-desc{opacity:1}
.product-price{font-family:var(--serif);font-size:20px;color:var(--gold2);font-weight:700}
.product-line{width:0;height:2px;background:var(--red);transition:width .4s;margin-top:12px}
.product-card:hover .product-line{width:60px}

/* WHY */
.why-section{background:var(--bg2);padding:100px 48px;border-top:1px solid var(--bd);border-bottom:1px solid var(--bd)}
.why-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.why-left{position:relative}
.big-quote{font-family:var(--serif);font-size:clamp(40px,5vw,72px);font-weight:900;line-height:1;
  color:var(--tx);margin-bottom:28px}
.big-quote span{color:var(--red2);font-style:italic}
.why-text{font-size:14px;color:var(--tx2);line-height:1.9;font-weight:300;max-width:420px}
.why-right{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.why-item{padding:28px;background:var(--bg3);border:1px solid var(--bd);border-radius:4px;
  transition:all .4s;position:relative;overflow:hidden}
.why-item::before{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:var(--red);transform:scaleX(0);transform-origin:left;transition:transform .4s}
.why-item:hover::before{transform:scaleX(1)}
.why-item:hover{border-color:rgba(185,28,28,.3);transform:translateY(-3px)}
.why-ico{font-size:28px;margin-bottom:14px}
.why-name{font-family:var(--serif);font-size:18px;font-weight:700;margin-bottom:6px}
.why-desc{font-size:12px;color:var(--tx2);line-height:1.7}

/* TESTIMONIALS */
.test-section{padding:100px 48px}
.test-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:48px}
.test-card{padding:32px;background:var(--bg2);border:1px solid var(--bd);border-radius:4px;position:relative}
.test-card::before{content:'"';font-family:var(--serif);font-size:80px;color:var(--red);opacity:.15;
  position:absolute;top:12px;left:20px;line-height:1}
.test-stars{color:var(--gold);font-size:12px;margin-bottom:16px}
.test-text{font-size:13px;color:var(--tx2);line-height:1.8;font-style:italic;margin-bottom:20px;position:relative;z-index:1}
.test-author{font-size:12px;font-weight:500;color:var(--tx);letter-spacing:.5px}

/* CONTACT */
.contact-section{background:var(--bg2);padding:100px 48px;border-top:1px solid var(--bd)}
.contact-inner{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:start}
.contact-title{font-family:var(--serif);font-size:clamp(36px,4vw,56px);font-weight:900;line-height:1;margin-bottom:24px}
.contact-title span{color:var(--red2);font-style:italic}
.contact-desc{font-size:14px;color:var(--tx2);line-height:1.9;max-width:380px;margin-bottom:36px}
.contact-item{display:flex;align-items:center;gap:16px;padding:20px;background:var(--bg3);border:1px solid var(--bd);border-radius:4px;margin-bottom:12px;text-decoration:none;transition:all .3s;color:var(--tx)}
.contact-item:hover{border-color:rgba(185,28,28,.4);transform:translateX(4px)}
.contact-item i{width:36px;height:36px;background:rgba(185,28,28,.15);border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--red2);font-size:14px}
.contact-item small{display:block;font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:var(--tx2);margin-bottom:2px}
.contact-item span{font-size:14px}
.map-placeholder{width:100%;aspect-ratio:16/9;background:var(--bg3);border:1px solid var(--bd);border-radius:4px;
  display:flex;align-items:center;justify-content:center;font-size:60px;opacity:.2;position:relative;overflow:hidden}
.map-placeholder::after{content:'Av. Carrera Pinto 1380, Conchalí';position:absolute;bottom:24px;left:50%;transform:translateX(-50%);
  font-size:12px;letter-spacing:1px;color:var(--tx2);opacity:1;white-space:nowrap}

/* FOOTER */
footer{background:var(--bg);border-top:1px solid var(--bd);padding:48px;display:flex;align-items:center;justify-content:space-between}
.footer-logo{font-family:var(--serif);font-size:20px;font-weight:900;color:var(--tx)}
.footer-copy{font-size:11px;color:var(--tx2);letter-spacing:.5px}
.footer-credit{font-size:11px;color:var(--tx2)}
.footer-credit span{color:var(--gold)}

/* WHATSAPP */
.wa{position:fixed;bottom:28px;right:28px;z-index:200;width:56px;height:56px;border-radius:50%;
  background:#25D366;display:flex;align-items:center;justify-content:center;
  box-shadow:0 4px 24px rgba(37,211,102,.35);font-size:24px;color:#fff;text-decoration:none;
  transition:all .3s}
.wa:hover{transform:scale(1.1);box-shadow:0 6px 32px rgba(37,211,102,.5)}

/* ANIMATIONS */
@keyframes fadeUp{from{opacity:0;transform:translateY(32px)}to{opacity:1;transform:translateY(0)}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}

.reveal{opacity:0;transform:translateY(28px);transition:opacity .7s ease,transform .7s ease}
.reveal.vis{opacity:1;transform:translateY(0)}
.reveal-delay-1{transition-delay:.1s}
.reveal-delay-2{transition-delay:.2s}
.reveal-delay-3{transition-delay:.3s}

@media(max-width:900px){
  .nav{padding:0 24px}.hero{padding:0 24px;padding-top:80px;flex-direction:column;align-items:flex-start;min-height:auto;padding-bottom:60px}
  .hero-visual{display:none}
  .section{padding:60px 24px}.why-grid,.contact-inner{grid-template-columns:1fr;gap:40px}
  .products-grid{grid-template-columns:1fr}.test-grid{grid-template-columns:1fr}
  .why-right{grid-template-columns:1fr}
  footer{flex-direction:column;gap:12px;text-align:center;padding:32px 24px}
  .strip{padding:14px 24px}
  .hero-stats{gap:24px}
}

